#if UNITY_EDITOR
using System;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using NUnit.Framework;
using Newtonsoft.Json.Linq;
namespace LastRail.Tests.EditMode {
 public sealed class BGunnerInterceptRuntimeTests {
  internal static BDirectAttackBasicLoop Create(BDirectAttackBasicLoopBinding binding,LastRail.Run.BBoardingEventsNodeSnapshot source,int capacity=10000){var m=typeof(BDirectAttackBasicLoop).GetMethod("CreateGunnerInterceptLocalRuntime");Assert.NotNull(m,"Missing explicit approved v08 native projectile/intercept factory");return (BDirectAttackBasicLoop)m.Invoke(null,new object[]{binding,source,BWaveBoardingRuntimeTests.Paths(binding.Composition.Attack),capacity});}
  static object Original(string name)=>typeof(BDirectAttackBasicLoopTests).GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);
  internal static BDirectAttackBasicLoopBinding Kyle(LastRail.Run.BBoardingEventsNodeSnapshot source,int distance=6000,string buffType="BCB01",int rank=5,int boundaryInterval=0,bool basicGeometry=false){
   var p=BWaveBoardingRuntimeTests.HitPacket(source.OriginalSource,false,true);p["stepTimeSpanTicks"]=100000;p["version"]="unity.combat-b.gunner-intercept-local-input.v1.20261004";p["provenance"]="LOCAL_APPROVED_INTERCEPT_NOT_ADMITTED_ABILITY";
   var profile=(JObject)Original("Owned");profile["accountId"]=source.OriginalSource.Capture()["origin"]["accountId"].DeepClone();var stat=((JArray)profile["operators"]).Single(x=>(string)x["operatorId"]=="op_kyle")["permanentStats"];if(boundaryInterval>0){stat["basicIntervalMs"]=boundaryInterval;((JArray)p["sourceEvidence"]).Add(new JObject{["sourceId"]="EXPLICIT_LOCAL_NEXT_REMAINDER_BOUNDARY_NOT_OPERATING_STATS",["sha256"]=BDirectAttackInput.Digest(profile).Substring(7)});}
   var e=((JArray)p["entities"]).Single(x=>(string)x["id"]=="op_mira");e["id"]="op_kyle";e["definitionId"]="op_kyle";e["attack"]=stat["attack"].DeepClone();e["defense"]=new JObject{["numerator"]=stat["defense"].ToString(),["denominator"]="1"};e["maxHp"]=stat["maxHp"].DeepClone();e["basicIntervalMicroseconds"]=(long)stat["basicIntervalMs"]*1000;
   var form=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,new[]{new BCombatSlot("car0","op_kyle")});p["formation"]=form.Capture();p["ownedProfileHash"]=BDirectAttackInput.Digest(profile);
   foreach(var g in (JArray)p["geometry"]){g["targetId"]="op_kyle";g["distanceMm"]=distance;if(source.OriginalSource.Waves.SelectMany(w=>w.Instances).Single(x=>x.InstanceId==(string)g["sourceId"]).DefinitionId=="enemy_spike_cart_gunner")g["maximumDistanceMm"]=24000;}
   if(basicGeometry)foreach(var enemy in source.OriginalSource.Waves.SelectMany(w=>w.Instances))((JArray)p["geometry"]).Add(new JObject{["sourceId"]="op_kyle",["targetId"]=enemy.InstanceId,["sourceSlot"]=0,["targetSlot"]=0,["distanceMm"]=1000,["maximumDistanceMm"]=1800,["observedTick"]=500,["validUntilTick"]=1000000,["eligible"]=true});
   var input=BDirectAttackInput.ReadGunnerInterceptLocalRuntime(p,BDirectAttackInput.Digest(p),form,profile,BDirectAttackInput.Digest(profile),(CombatDefinitionIndex)Original("Definition"),source.OriginalSource);
   var old=BWaveBoardingRuntimeTests.WaveBinding(source.OriginalSource,null,null,buffType);var packet=old.Composition.Capture();packet["attackInputHash"]=input.OriginalHash;packet["departure"]["cars"][0]["occupant"]["operatorId"]="op_kyle";packet["departure"]["cars"][0]["rank"]=rank;var composition=new BDirectAttackBuffBinding(input,(BCarriageBuffDefinitions)Original("Defs"),packet,BDirectAttackInput.Digest(packet));
   var routes=old.Capture();routes["compositionHash"]=composition.OriginalHash;foreach(var route in (JArray)routes["targets"]){if((string)route["sourceId"]=="op_mira")route["sourceId"]="op_kyle";else route["targetId"]="op_kyle";}return new BDirectAttackBasicLoopBinding(composition,routes,BDirectAttackInput.Digest(routes));
  }
  [Test] public void KyleCompletesAtContactAndBlocksExactlyOneSixMetreBullet(){var source=BBoardingEventsTests.Source(2);var b=Kyle(source);var s=Create(b,source);int hp=s.Hp("op_kyle");s.Advance("launch",54000000,540);s.Advance("contact",2500000,25);Assert.AreEqual(hp,s.Hp("op_kyle"));var shots=(JArray)s.Capture()["gunnerIntercept"]["projectiles"];Assert.AreEqual(1,shots.Count(x=>(string)x["terminal"]=="INTERCEPTED"));Assert.IsTrue(shots.All(x=>(string)x["terminal"]!="HIT"));Assert.IsFalse((bool)s.Capture()["namedInterceptionAbilityBound"]);}
  [Test] public void SerializedProjectileCheckpointPreservesJsonNullAndStrictReplay(){var source=BBoardingEventsTests.Source(2);var binding=Kyle(source);var native=Create(binding,source);native.Advance("serialized-launch",54000000,540);native.Advance("serialized-contact",2500000,25);var captured=native.Capture();var parsed=JObject.Parse(captured.ToString());Assert.IsTrue(JToken.DeepEquals(captured,parsed),"Capture must keep identical token types after JSON file serialization");var restored=BDirectAttackBasicLoop.RestoreGunnerInterceptLocalRuntime(parsed,BDirectAttackInput.Digest(parsed),binding,source,BWaveBoardingRuntimeTests.Paths(binding.Composition.Attack),10000);Assert.IsTrue(JToken.DeepEquals(parsed,restored.Capture()));}
  [Test] public void ApprovedPolicyUsesIndependentHasteAndPhaseCeil(){var t=typeof(BDirectAttackBasicLoop).Assembly.GetType("LastRail.Battle.BInterceptApprovedLocalPolicy");Assert.NotNull(t,"Missing immutable v08 policy");var k=t.GetMethod("Ticks");Assert.NotNull(k);var result=(long[])k.Invoke(null,new object[]{"op_kyle",10000L,0L});CollectionAssert.AreEqual(new long[]{25,45},result);result=(long[])k.Invoke(null,new object[]{"op_sable",10000L,3000L});CollectionAssert.AreEqual(new long[]{16,50},result);}
  static JArray Shots(BDirectAttackBasicLoop s)=>(JArray)s.Capture()["gunnerIntercept"]["projectiles"];
  static JArray Actions(BDirectAttackBasicLoop s)=>(JArray)s.Capture()["gunnerIntercept"]["interception"]["actions"];
  [Test] public void OneStepTooLateRejectsWithoutTimingSourceOrCost(){var source=BBoardingEventsTests.Source(2);var b=Kyle(source,5760);var s=Create(b,source);s.Advance("launch",54000000,540);Assert.AreEqual(0,Actions(s).Count);Assert.AreEqual(0,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]);Assert.AreEqual(0,((JArray)s.Capture()["state"]["buffs"]["actions"]).Count);int hp=s.Hp("op_kyle");s.Advance("contact",2400000,24);Assert.Less(s.Hp("op_kyle"),hp);Assert.AreEqual("HIT",(string)Shots(s)[0]["terminal"]);}
  [Test] public void PreparationFailureChargesActualTimeAndSnapshotRecoveryOnlyOnce(){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source),source);s.Advance("launch",54000000,540);s.Advance("spent100",1000000,10);string shot=(string)Shots(s)[0]["id"];s.CancelLocalGunnerShot("cancel",shot);Assert.AreEqual("RECOVERY",(string)Actions(s)[0]["phase"]);Assert.AreEqual(595,(long)Actions(s)[0]["endTick"]);Assert.AreEqual(595,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]);s.CancelLocalGunnerShot("cancel-again",shot);Assert.AreEqual(595,(long)Actions(s)[0]["endTick"]);Assert.AreEqual(595,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]);}
  [Test] public void ManualOccupationPrecedesNewInterceptionAndCannotCancelAcceptedAction(){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source),source);s.Advance("before",53900000,539);s.ObserveLocalManualOccupation("manual","op_kyle",566);s.Advance("launch",100000,1);Assert.AreEqual(0,Actions(s).Count);s.Advance("contact",2500000,25);Assert.AreEqual("HIT",(string)Shots(s)[0]["terminal"]);var accepted=Create(Kyle(source),source);accepted.Advance("launch",54000000,540);var before=accepted.Capture();Assert.Throws<ArgumentException>(()=>accepted.ObserveLocalManualOccupation("manual","op_kyle",566));Assert.IsTrue(JToken.DeepEquals(before,accepted.Capture()));}
  [Test] public void FlyingShotSurvivesSourceDeathAndBlocksWaveUntilTerminal(){var source=BBoardingEventsTests.Source(2);var p=BWaveBoardingRuntimeTests.HitPacket(source.OriginalSource,true,true);p["stepTimeSpanTicks"]=100000;foreach(var g in ((JArray)p["geometry"]).Where(x=>(string)x["sourceId"]!="op_mira")){g["distanceMm"]=6000;if(source.OriginalSource.Waves.SelectMany(w=>w.Instances).Single(x=>x.InstanceId==(string)g["sourceId"]).DefinitionId=="enemy_spike_cart_gunner")g["maximumDistanceMm"]=24000;}var profile=BWaveBoardingRuntimeTests.LocalBoundaryAttackProfile(p);var high=new JObject{["numerator"]="50000",["denominator"]="1"};((JArray)profile["operators"]).Single(x=>(string)x["operatorId"]=="op_mira")["permanentStats"]["attack"]=high.DeepClone();((JArray)p["entities"]).Single(x=>(string)x["id"]=="op_mira")["attack"]=high.DeepClone();var b=BWaveBoardingRuntimeTests.ManualOperators(BWaveBoardingRuntimeTests.WaveBinding(source.OriginalSource,p,profile));var s=Create(b,source);s.Advance("launch",54000000,540);string shotSource=(string)Shots(s)[0]["sourceId"];s.ApplyWaveBasic("kill-source","op_mira",shotSource,1);Assert.AreEqual(0,s.Hp(shotSource));Assert.AreEqual("FLYING",(string)Shots(s)[0]["terminal"]);int hp=s.Hp("op_mira");s.Advance("contact",2500000,25);Assert.AreEqual("HIT",(string)Shots(s)[0]["terminal"]);Assert.Less(s.Hp("op_mira"),hp);}
  [Test] public void GunnerNativeRestorePauseAndFramePartitionPreserveSingleOwnedState(){var source=BBoardingEventsTests.Source(2);var b=Kyle(source);var s=Create(b,source);s.Advance("launch",54000000,540);s.SetPaused("pause",true);var cache=s.Capture();var restored=BDirectAttackBasicLoop.RestoreGunnerInterceptLocalRuntime(cache,BDirectAttackInput.Digest(cache),b,source,BWaveBoardingRuntimeTests.Paths(b.Composition.Attack),10000);s.Advance("paused",10000000,100);restored.Advance("paused",10000000,100);Assert.AreEqual(540,s.Tick);s.SetPaused("resume",false);restored.SetPaused("resume",false);s.Advance("all",7000000,70);restored.Advance("all",7000000,70);Assert.IsTrue(JToken.DeepEquals(s.Capture(),restored.Capture()));var a=Create(b,source);var z=Create(b,source);a.Advance("all",65000000,650);z.Advance("one",55000000,550);z.Advance("two",10000000,100);foreach(string key in new[]{"boarding","waveEntry","gunnerIntercept"})Assert.IsTrue(JToken.DeepEquals(a.Capture()[key],z.Capture()[key]),key);Assert.IsTrue(JToken.DeepEquals(a.Capture()["state"]["direct"]["next"],z.Capture()["state"]["direct"]["next"]));}
  [Test] public void CapacityFailureCannotPublishPartialProjectileOrHp(){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source),source,60);var before=s.Capture();Assert.Catch(()=>s.Advance("overflow",1000000000,10000));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [TestCase("op_kyle",0,25,45)][TestCase("op_kyle",3000,20,35)][TestCase("op_sable",0,20,65)][TestCase("op_sable",3000,16,50)]
  public void PerPhaseApprovedTimesDoNotConsumeAttackOrSkillHaste(string actor,long haste,long preparation,long recovery){var result=BInterceptApprovedLocalPolicy.Ticks(actor,10000,haste);CollectionAssert.AreEqual(new[]{preparation,recovery},result);CollectionAssert.AreEqual(new long[]{1,1},BInterceptApprovedLocalPolicy.Ticks(actor,1000000,9007199254740991));}
  [Test] public void Bcb03UsesCapturedInterceptionSource(){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source,6000,"BCB03"),source);s.Advance("launch",54000000,540);Assert.AreEqual(560,(long)Actions(s)[0]["readyTick"]);Assert.AreEqual(595,(long)Actions(s)[0]["endTick"]);Assert.AreEqual(3000,(long)Actions(s)[0]["timingSource"]["interceptionHasteBps"]);Assert.AreEqual(0,(long)Actions(s)[0]["timingSource"]["skillHasteBps"]);}
  [Test] public void OriginalNextRemainder400PlusKyle700Is1100Milliseconds(){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source,6000,"BCB01",5,800,true),source);s.Advance("before",53900000,539);Assert.AreEqual(580,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]);s.Advance("launch",100000,1);Assert.AreEqual(650,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]);Assert.AreEqual(110,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]-s.Tick);s.Advance("recovery",7000000,70);Assert.AreEqual(610,s.Tick);Assert.AreEqual(650,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]);s.Advance("remaining",3900000,39);Assert.AreEqual(650,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]);var hit=s.Advance("due",100000,1);Assert.IsTrue(hit.Hits.Any(h=>h.Attack.SourceId=="op_kyle"));}
  [Test] public void FasterAttackGroupAndSkillHasteCannotAccelerateInterception(){var source=BBoardingEventsTests.Source(2);var skill=Create(Kyle(source,6000,"BCB02"),source);skill.Advance("launch",54000000,540);Assert.AreEqual(565,(long)Actions(skill)[0]["readyTick"]);Assert.AreEqual(610,(long)Actions(skill)[0]["endTick"]);Assert.AreEqual(0,(long)Actions(skill)[0]["timingSource"]["interceptionHasteBps"]);}
  [TestCase(1,10)][TestCase(2,15)][TestCase(3,20)][TestCase(4,25)][TestCase(5,30)]
  public void OriginalBcb03RanksUseOnlyVerifiedHaste(int rank,long reduction){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source,6000,"BCB03",rank),source);s.Advance("launch",54000000,540);Assert.AreEqual(reduction*100,(long)Actions(s)[0]["timingSource"]["interceptionHasteBps"]);}
  [Test] public void ManualBasicCannotBypassExistingManualOccupation(){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source,5760,"BCB01",5,800,true),source);s.Advance("before",57900000,579);s.ObserveLocalManualOccupation("manual","op_kyle",600);s.Advance("due",100000,1);var before=s.Capture();Assert.Throws<ArgumentException>(()=>s.ApplyWaveBasic("bypass","op_kyle",source.OriginalSource.Waves[0].Instances[0].InstanceId,1));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void CanonicalKyleLowHpPassiveAddsDefenseAfterStatMultipliers(){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source),source);s.ObserveLocalManualOccupation("manual","op_kyle",100000);int count=0;while(s.Hp("op_kyle")>=1000&&count<100)s.Advance("damage"+count++,20000000,200);Assert.Greater(s.Hp("op_kyle"),0);Assert.Less(s.Hp("op_kyle"),1000);var result=s.Advance("below-half",20000000,200);Assert.Greater(result.Hits.Count,0);Assert.IsTrue(result.Hits.All(h=>(string)h.Attack.Calculation["effectiveDefense"]["numerator"]=="333"));}
  static BDirectAttackBasicLoopBinding MiraBoundary(LastRail.Run.BBoardingEventsNodeSnapshot source,bool lowHp=false){var p=BWaveBoardingRuntimeTests.HitPacket(source.OriginalSource,true,true);p["stepTimeSpanTicks"]=100000;foreach(var g in ((JArray)p["geometry"]).Where(x=>(string)x["sourceId"]!="op_mira")){g["distanceMm"]=24000;if(source.OriginalSource.Waves.SelectMany(w=>w.Instances).Single(x=>x.InstanceId==(string)g["sourceId"]).DefinitionId=="enemy_spike_cart_gunner")g["maximumDistanceMm"]=24000;}var profile=BWaveBoardingRuntimeTests.LocalBoundaryAttackProfile(p);var high=new JObject{["numerator"]="50000",["denominator"]="1"};var stat=((JArray)profile["operators"]).Single(x=>(string)x["operatorId"]=="op_mira")["permanentStats"];stat["attack"]=high.DeepClone();var actor=((JArray)p["entities"]).Single(x=>(string)x["id"]=="op_mira");actor["attack"]=high.DeepClone();stat["basicIntervalMs"]=10;actor["basicIntervalMicroseconds"]=10000;if(lowHp){stat["maxHp"]=1;actor["maxHp"]=1;foreach(var g in ((JArray)p["geometry"]).Where(x=>(string)x["sourceId"]!="op_mira"&&(string)x["sourceId"]!=source.OriginalSource.Waves[0].Instances[0].InstanceId))g["distanceMm"]=6000;p["initialShields"]=new JArray(new JObject{["targetId"]="op_mira",["sourceEntity"]="LOCAL_BOUNDARY_SHIELD",["sourceAbility"]="LOCAL_BOUNDARY_SHIELD",["effectIndex"]=0,["amount"]=36,["expiryTick"]=100000});}return BWaveBoardingRuntimeTests.ManualOperators(BWaveBoardingRuntimeTests.WaveBinding(source.OriginalSource,p,profile));}
  [Test] public void OldFlyingTargetLifeMissesAfterNativeTargetDown(){var source=BBoardingEventsTests.Source(2);var s=Create(MiraBoundary(source,true),source);s.Advance("old-flight",94000000,940);Assert.IsTrue(Shots(s).Any(x=>(string)x["terminal"]=="FLYING"));s.Advance("target-down",9000000,90);Assert.AreEqual(0,s.Hp("op_mira"));s.Advance("old-contact",10000000,100);Assert.IsTrue(Shots(s).Any(x=>(string)x["terminal"]=="MISS"));Assert.AreEqual(0,s.Hp("op_mira"));Assert.IsTrue(Shots(s).Where(x=>(string)x["terminal"]=="MISS").All(x=>(long)x["targetGeneration"]==1));}
  [Test] public void TwoNativeWavesCannotClearUntilLastFlyingProjectileTerminates(){var source=BBoardingEventsTests.Source(2);var b=MiraBoundary(source);var s=Create(b,source);string kept=source.OriginalSource.Waves[0].Instances[0].InstanceId;int command=0;
   void KillRegistered(bool keep){foreach(var life in ((JArray)s.Capture()["boarding"]["lives"]).Where(x=>(bool)x["registered"]&&(bool)x["targetable"]).ToArray()){string id=(string)life["id"];if(keep&&id==kept)continue;if((long)s.Capture()["state"]["direct"]["next"]["op_mira"]>s.Tick)s.Advance("native-cooldown"+command++,100000,1);s.ApplyWaveBasic("kill"+command++,"op_mira",id,(long)life["generation"]);}}
   s.Advance("launch",54000000,540);KillRegistered(true);for(int n=0;n<50&&(int)s.Capture()["waveEntry"]["cursor"]<source.OriginalSource.Waves[0].Count;n++){s.Advance("enter"+n,3000000,30);KillRegistered(true);}Assert.AreEqual(source.OriginalSource.Waves[0].Count,(int)s.Capture()["waveEntry"]["cursor"]);
   for(int n=0;n<50&&source.OriginalSource.Waves[0].Instances.Any(x=>x.InstanceId!=kept&&s.Hp(x.InstanceId)>0);n++){s.Advance("remaining-entrance"+n,1000000,10);KillRegistered(true);}
   for(int n=0;n<50&&!Shots(s).Any(x=>(string)x["terminal"]=="FLYING"&&(long)x["contactTick"]>s.Tick+2);n++)s.Advance("flight"+n,1000000,10);Assert.IsTrue(Shots(s).Any(x=>(string)x["terminal"]=="FLYING"&&(long)x["contactTick"]>s.Tick+2));KillRegistered(false);Assert.IsTrue(source.OriginalSource.Waves[0].Instances.All(x=>s.Hp(x.InstanceId)==0));Assert.AreEqual(0,(long)s.Capture()["waveEntry"]["gapUntil"]);Assert.IsFalse((bool)s.Capture()["waveEntry"]["unknownProjectile"]);
   s.Advance("resolve-flight",10000000,100);Assert.Greater((long)s.Capture()["waveEntry"]["gapUntil"],0);s.Advance("gap",20000000,200);for(int n=0;n<80&&s.Outcome=="RUNNING";n++){s.Advance("second"+n,6000000,60);KillRegistered(false);}Assert.AreEqual("VICTORY",s.Outcome);Assert.NotNull(s.Capture()["gunnerIntercept"]["terminal"],"Missing explicit projectile terminal ownership");Assert.IsTrue((bool)s.Capture()["gunnerIntercept"]["terminal"]);Assert.IsTrue((bool)s.Capture()["gunnerIntercept"]["interception"]["terminal"]);Assert.IsFalse(Shots(s).Any(x=>(string)x["terminal"]=="FLYING"));Assert.AreEqual(2,((JArray)s.Capture()["waveEntry"]["events"]).Count(x=>(string)x["kind"]=="WAVE_CLEAR"));var restored=BDirectAttackBasicLoop.RestoreGunnerInterceptLocalRuntime(s.Capture(),BDirectAttackInput.Digest(s.Capture()),b,source,BWaveBoardingRuntimeTests.Paths(b.Composition.Attack),10000);Assert.IsTrue(JToken.DeepEquals(s.Capture(),restored.Capture()));}
  [Test] public void ProjectileTargetGenerationBelongsToNativeHpOwner(){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source),source);Assert.NotNull(s.Capture()["state"]["direct"]["projectileTargetGenerations"],"Missing Session-owned target lifetime generations");Assert.AreEqual(1,(long)s.Capture()["state"]["direct"]["projectileTargetGenerations"]["op_kyle"]);}
  [Test] public void TerminalOwnerReleasesAcceptedReservationWithoutExtraDamageOrNextReset(){var source=BBoardingEventsTests.Source(2);var s=Create(Kyle(source),source);s.Advance("launch",54000000,540);var flags=BindingFlags.Instance|BindingFlags.NonPublic;var owner=typeof(BDirectAttackBasicLoop).GetField("interception",flags).GetValue(s);var shotOwner=typeof(BDirectAttackBasicLoop).GetField("projectiles",flags).GetValue(s);var native=(BDirectAttackBuffSession)typeof(BDirectAttackBasicLoop).GetField("session",flags).GetValue(s);var method=owner.GetType().GetMethod("Terminal",flags);Assert.NotNull(method,"Missing terminal release for accepted interception action");int hp=s.Hp("op_kyle");long due=(long)s.Capture()["state"]["direct"]["next"]["op_kyle"];long sequence=1000;method.Invoke(owner,new object[]{shotOwner,native,(Func<long>)(()=>++sequence)});Assert.AreEqual("TERMINAL",(string)Actions(s)[0]["phase"]);Assert.IsNull((string)Shots(s)[0]["reservedBy"]);Assert.AreEqual(hp,s.Hp("op_kyle"));Assert.AreEqual(due,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]);var state=s.Capture()["gunnerIntercept"];method.Invoke(owner,new object[]{shotOwner,native,(Func<long>)(()=>++sequence)});Assert.IsTrue(JToken.DeepEquals(state,s.Capture()["gunnerIntercept"]));}
  [Test] public void InterceptInputIsExplicitAndOldWaveRosterStaysRestricted(){Assert.NotNull(typeof(BDirectAttackInput).GetMethod("ReadGunnerInterceptLocalRuntime"),"Missing explicit LOCAL Kyle/source intake boundary");}
  [Test] public void GunnerLaunchHasRealFlightBeforeNativeHpImpact(){var source=BBoardingEventsTests.Source(2);var p=BWaveBoardingRuntimeTests.HitPacket(source.OriginalSource,false,true);p["stepTimeSpanTicks"]=100000;foreach(var g in (JArray)p["geometry"]){g["distanceMm"]=6000;if(source.OriginalSource.Waves.SelectMany(w=>w.Instances).Single(x=>x.InstanceId==(string)g["sourceId"]).DefinitionId=="enemy_spike_cart_gunner")g["maximumDistanceMm"]=24000;}var b=BWaveBoardingRuntimeTests.WaveBinding(source.OriginalSource,p);var s=Create(b,source);int hp=s.Hp("op_mira");s.Advance("launch",54000000,540);var shots=(JArray)s.Capture()["gunnerIntercept"]["projectiles"];Assert.Greater(shots.Count,0);Assert.IsTrue(shots.All(x=>(string)x["terminal"]=="FLYING"));Assert.AreEqual(hp,s.Hp("op_mira"));s.Advance("before-contact",2400000,24);Assert.AreEqual(hp,s.Hp("op_mira"));var result=s.Advance("contact",100000,1);Assert.Less(s.Hp("op_mira"),hp);Assert.IsTrue(result.Hits.Any(x=>x.Attack.SourceId==source.OriginalSource.Waves[0].Instances[0].InstanceId));Assert.IsTrue(shots.All(x=>(long)x["contactTick"]-(long)x["launchTick"]==25));Assert.IsFalse(s.OrdinaryRuntimeGeometrySupported);}
 }
